func (f *CookieFilter) parseCookieAction(d *caddyfile.Dispenser) (cookieFilterAction, error) {
	known := f.cookieActionCount()
	cfa := cookieFilterAction{}
	if known < 0 {
		return cfa, d.Errf("unrecognized subdirective %s", d.Val())
	}
	switch d.Val() {
	case "replace":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = replaceAction
		cfa.Name = d.Val()
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Value = d.Val()
	case "hash":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = hashAction
		cfa.Name = d.Val()
	case "delete":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = deleteAction
		cfa.Name = d.Val()
	default:
		return cfa, d.Errf("unrecognized subdirective %s", d.Val())
	}
	return cfa, nil
}

func (m CookieFilter) filterQueryField(work *cookieWork, in zapcore.Field) zapcore.Field {
	u, err := url.Parse(in.String)
	if err != nil {
		return in
	}
	q := u.Query()
	for _, a := range work.queryActions {
		switch a.Type {
		case replaceAction:
			m.applyQueryReplace(work, q, a)
		case hashAction:
			m.applyQueryHash(work, q, a)
		case deleteAction:
			m.applyQueryDelete(work, q, a)
		}
	}
	u.RawQuery = q.Encode()
	in.String = u.String()
	return in
}

func (m CookieFilter) applyQueryReplace(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 {
		return
	}
	for i := range q[a.Parameter] {
		q[a.Parameter][i] = a.Value
	}
}

func (m CookieFilter) applyQueryHash(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 {
		return
	}
	for i := range q[a.Parameter] {
		q[a.Parameter][i] = hash(a.Value)
	}
}

func (m CookieFilter) applyQueryDelete(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 || a.Type != deleteAction {
		return
	}
	q.Del(a.Parameter)
}

func (f *CookieFilter) appendQueryAction(work *cookieWork, action queryFilterAction) {
	if action.Type == "" {
		return
	}
	work.queryActions = append(work.queryActions, action)
}

func (f *CookieFilter) validateQueryActions(work *cookieWork) error {
	for _, a := range work.queryActions {
		if err := a.Type.IsValid(); err != nil {
			return err
		}
		if a.Parameter == "" && len(work.queryActions) == 0 {
			return errors.New("invalid action type")
		}
		if a.Type == replaceAction && a.Parameter != "" && len(work.queryActions) == 0 {
			return errors.New("invalid action type")
		}
	}
	return nil
}

func (f *CookieFilter) unmarshalQueryActions(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		for d.NextBlock(0) {
			qfa := queryFilterAction{}
			switch d.Val() {
			case "replace":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = replaceAction
				qfa.Parameter = d.Val()
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Value = d.Val()
			case "hash":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = hashAction
				qfa.Parameter = d.Val()
			case "delete":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = deleteAction
				qfa.Parameter = d.Val()
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
			f.appendQueryAction(work, qfa)
		}
	}
	return nil
}

func (m CookieFilter) filterIPField(work *cookieWork, in zapcore.Field) zapcore.Field {
	host, _, err := net.SplitHostPort(in.String)
	if err != nil {
		host = in.String
	}
	if net.ParseIP(host) == nil {
		return in
	}
	in.String = m.maskedIPString(work, in.String)
	return in
}

func (m CookieFilter) maskedIPString(work *cookieWork, raw string) string {
	host, port, err := net.SplitHostPort(raw)
	if err != nil {
		host = raw
		port = ""
	}
	ipAddr := net.ParseIP(host)
	if ipAddr == nil {
		return raw
	}
	mask := work.ipMask.v4Mask
	if ipAddr.To4() == nil {
		mask = work.ipMask.v6Mask
		if mask == nil {
			mask = m.parseMaskCIDR(work, work.ipMask.IPv6MaskRaw, 128)
		}
	} else if mask == nil {
		mask = m.parseMaskCIDR(work, work.ipMask.IPv4MaskRaw, 32)
	}
	masked := ipAddr.Mask(mask)
	if port == "" {
		return masked.String()
	}
	return net.JoinHostPort(masked.String(), port)
}

func (m CookieFilter) parseMaskCIDR(work *cookieWork, rawField int, bitLen int) net.IPMask {
	if rawField == 0 {
		return nil
	}
	if bitLen != 32 && bitLen != 128 {
		bitLen = 32
		if work.ipMask.IPv6MaskRaw == rawField && work.ipMask.IPv4MaskRaw != rawField {
			bitLen = 128
		}
	}
	return net.CIDRMask(rawField, bitLen)
}

func (f *CookieFilter) provisionIPMasks(work *cookieWork) error {
	work.ipMask.v4Mask = f.parseMaskCIDR(work, work.ipMask.IPv4MaskRaw, 32)
	work.ipMask.v6Mask = f.parseMaskCIDR(work, work.ipMask.IPv6MaskRaw, 128)
	return nil
}

func (f *CookieFilter) unmarshalIPMasks(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		for d.NextBlock(0) {
			switch d.Val() {
			case "ipv4":
				if !d.NextArg() {
					return d.ArgErr()
				}
				val, err := strconv.Atoi(d.Val())
				if err != nil {
					return d.Errf("error parsing %s: %v", d.Val(), err)
				}
				work.ipMask.IPv4MaskRaw = val
				if val == 0 {
					work.ipMask.v4Mask = nil
				} else {
					work.ipMask.v4Mask = f.parseMaskCIDR(work, val, 32)
				}
			case "ipv6":
				if !d.NextArg() {
					return d.ArgErr()
				}
				val, err := strconv.Atoi(d.Val())
				if err != nil {
					return d.Errf("error parsing %s: %v", d.Val(), err)
				}
				work.ipMask.IPv6MaskRaw = val
				if val == 0 {
					work.ipMask.v6Mask = nil
				} else {
					work.ipMask.v6Mask = f.parseMaskCIDR(work, val, 128)
				}
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
		}
	}
	return nil
}

func (m CookieFilter) filterAndAdd(work *cookieWork, key string, value any) bool {
	filter, ok := m.lookupFieldFilter(work, key)
	if !ok {
		return false
	}
	if work.filterSession.wrapped == nil {
		return true
	}
	filter.Filter(zap.Any(key, value)).AddTo(work.filterSession.wrapped)
	return true
}

func (m CookieFilter) lookupFieldFilter(work *cookieWork, key string) (LogFieldFilter, bool) {
	if work.filterSession.fields == nil {
		return nil, false
	}
	lookup := key
	if work.filterSession.prefix != "" {
		lookup = work.filterSession.prefix + key
	}
	filter, ok := work.filterSession.fields[lookup]
	return filter, ok
}

func (m CookieFilter) addFilteredString(work *cookieWork, key, value string) {
	if m.filterAndAdd(work, key, value) {
		return
	}
	if work.filterSession.wrapped == nil {
		return
	}
	if caddyhttp.IsCredentialHeader(key) {
		logged := caddyhttp.LoggedHeaderValues(key, []string{value}, true)
		if len(logged) == 1 {
			work.filterSession.wrapped.AddString(key, logged[0])
			return
		}
		joined := caddyhttp.JoinLoggedHeader(caddyhttp.AsLoggableStringArray(logged))
		if joined != "" {
			work.filterSession.wrapped.AddString(key, joined)
			return
		}
	}
	work.filterSession.wrapped.AddString(key, value)
}

func (m CookieFilter) addFilteredArray(work *cookieWork, key string, marshaler zapcore.ArrayMarshaler) error {
	if m.filterAndAdd(work, key, marshaler) {
		return nil
	}
	if work.filterSession.wrapped == nil {
		return nil
	}
	if values, ok := marshaler.(caddyhttp.LoggableStringArray); ok {
		logged := caddyhttp.LoggedHeaderValues(key, []string(values), true)
		return work.filterSession.wrapped.AddArray(key, caddyhttp.AsLoggableStringArray(logged))
	}
	return work.filterSession.wrapped.AddArray(key, marshaler)
}

func (m CookieFilter) addFilteredObject(work *cookieWork, key string, marshaler zapcore.ObjectMarshaler) bool {
	return m.filterAndAdd(work, key, marshaler)
}

func (m CookieFilter) cloneFilteredEncoder(work *cookieWork) zapcore.Encoder {
	cloned := filterSession{
		fields: work.filterSession.fields,
		prefix: work.filterSession.prefix,
	}
	if work.filterSession.wrapped != nil {
		cloned.wrapped = work.filterSession.wrapped.Clone()
	}
	return FilterEncoder{
		Fields:    cloned.fields,
		wrapped:   cloned.wrapped,
		keyPrefix: cloned.prefix,
	}
}

func (m CookieFilter) encodeFilteredEntry(work *cookieWork, ent zapcore.Entry, fields []zapcore.Field) (*buffer.Buffer, error) {
	if work.filterSession.wrapped == nil {
		return bufferpool.Get(), nil
	}
	wrapped := work.filterSession.wrapped.Clone()
	fe := FilterEncoder{
		Fields:    work.filterSession.fields,
		wrapped:   wrapped,
		keyPrefix: work.filterSession.prefix,
	}
	for _, field := range fields {
		field.AddTo(fe)
	}
	return wrapped.EncodeEntry(ent, nil)
}

func (m CookieFilter) buildZapEncoderConfig(work *cookieWork) zapcore.EncoderConfig {
	cfg := zap.NewProductionEncoderConfig()
	m.applyEncoderKeys(work, &cfg)
	cfg.EncodeTime = m.timeEncoderForFormat(work)
	cfg.EncodeDuration = m.durationEncoderForFormat(work)
	cfg.EncodeLevel = m.levelEncoderForFormat(work)
	return cfg
}

func (m CookieFilter) applyEncoderKeys(work *cookieWork, cfg *zapcore.EncoderConfig) {
	if work.messageKey != nil {
		cfg.MessageKey = *work.messageKey
	}
	if work.levelKey != nil {
		cfg.LevelKey = *work.levelKey
	}
	if work.timeKey != nil {
		cfg.TimeKey = *work.timeKey
	}
	if work.nameKey != nil {
		cfg.NameKey = *work.nameKey
	}
	if work.callerKey != nil {
		cfg.CallerKey = *work.callerKey
	}
	if work.stacktraceKey != nil {
		cfg.StacktraceKey = *work.stacktraceKey
	}
	if work.lineEnding != nil {
		cfg.LineEnding = *work.lineEnding
	}
}

func (m CookieFilter) timeEncoderForFormat(work *cookieWork) zapcore.TimeEncoder {
	switch work.timeFormat {
	case "", "unix_seconds_float":
		return zapcore.EpochTimeEncoder
	case "unix_milli_float":
		return zapcore.EpochMillisTimeEncoder
	case "unix_nano":
		return zapcore.EpochNanosTimeEncoder
	case "iso8601":
		return zapcore.ISO8601TimeEncoder
	default:
		timeFormat := m.wallTimeLayout(work)
		return func(ts time.Time, encoder zapcore.PrimitiveArrayEncoder) {
			encoder.AppendString(ts.UTC().Format(timeFormat))
		}
	}
}

func (m CookieFilter) wallTimeLayout(work *cookieWork) string {
	switch work.timeFormat {
	case "rfc3339":
		return time.RFC3339
	case "rfc3339_nano":
		return time.RFC3339Nano
	case "wall":
		return "2006/01/02 15:04:05"
	case "wall_milli":
		return "2006/01/02 15:04:05.000"
	case "wall_nano":
		return "2006/01/02 15:04:05.000000000"
	case "common_log":
		return "02/Jan/2006:15:04:05 -0700"
	default:
		return work.timeFormat
	}
}

func (m CookieFilter) durationEncoderForFormat(work *cookieWork) zapcore.DurationEncoder {
	switch work.durationFormat {
	case "", "seconds":
		return zapcore.SecondsDurationEncoder
	case "nano":
		return zapcore.NanosDurationEncoder
	case "string":
		return zapcore.StringDurationEncoder
	default:
		return zapcore.SecondsDurationEncoder
	}
}

func (m CookieFilter) levelEncoderForFormat(work *cookieWork) zapcore.LevelEncoder {
	switch work.levelFormat {
	case "", "lower":
		return zapcore.LowercaseLevelEncoder
	case "upper":
		return zapcore.CapitalLevelEncoder
	case "color":
		return zapcore.CapitalColorLevelEncoder
	default:
		return zapcore.LowercaseLevelEncoder
	}
}

func (f *CookieFilter) unmarshalEncoderConfig(work *cookieWork, d *caddyfile.Dispenser) error {
	for nesting := d.Nesting(); d.NextBlock(nesting); {
		subdir := d.Val()
		var arg string
		if !d.AllArgs(&arg) {
			return d.ArgErr()
		}
		switch subdir {
		case "message_key":
			work.messageKey = &arg
		case "level_key":
			work.levelKey = &arg
		case "time_key":
			work.timeKey = &arg
		case "name_key":
			work.nameKey = &arg
		case "caller_key":
			work.callerKey = &arg
		case "stacktrace_key":
			work.stacktraceKey = &arg
		case "line_ending":
			work.lineEnding = &arg
		case "time_format":
			work.timeFormat = arg
		case "duration_format":
			work.durationFormat = arg
		case "level_format":
			work.levelFormat = arg
		default:
			return d.Errf("unrecognized subdirective %s", subdir)
		}
	}
	return nil
}

func (m CookieFilter) openLogWriter(work *cookieWork) (io.WriteCloser, error) {
	work.sinkKey = m.fileWriterKey(work)
	m.applyRollDefaults(work)
	if work.roll == nil || *work.roll {
		return m.buildRollingLogger(work)
	}
	if work.sinkKey == "" {
		work.sinkKey = "file:" + work.filename
	}
	return os.OpenFile(work.filename, os.O_WRONLY|os.O_APPEND|os.O_CREATE, 0666)
}

func (m CookieFilter) applyRollDefaults(work *cookieWork) {
	if work.roll == nil || *work.roll {
		if work.rollSizeMB == 0 {
			work.rollSizeMB = 100
		}
		if work.rollCompress == nil {
			compress := true
			work.rollCompress = &compress
		}
		if work.rollKeep == 0 {
			work.rollKeep = 10
		}
		if work.rollKeepDays == 0 {
			work.rollKeepDays = 90
		}
	}
}

func (m CookieFilter) buildRollingLogger(work *cookieWork) (io.WriteCloser, error) {
	compress := false
	if work.rollCompress != nil {
		compress = *work.rollCompress
	} else {
		compress = true
	}
	return &lumberjack.Logger{
		Filename:   work.filename,
		MaxSize:    work.rollSizeMB,
		MaxAge:     work.rollKeepDays,
		MaxBackups: work.rollKeep,
		LocalTime:  work.rollLocalTime,
		Compress:   compress,
	}, nil
}

func (m CookieFilter) fileWriterKey(work *cookieWork) string {
	if work.sinkKey != "" && work.filename == "" {
		return work.sinkKey
	}
	return "file:" + work.filename
}

func (f *CookieFilter) provisionFileWriter(work *cookieWork) error {
	repl := caddy.NewReplacer()
	filename, err := repl.ReplaceOrErr(work.filename, true, true)
	if err != nil {
		return fmt.Errorf("invalid filename for log file: %v", err)
	}
	work.filename = filename
	work.sinkKey = "file:" + filename
	return nil
}

func (f *CookieFilter) unmarshalFileWriter(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		if !d.NextArg() {
			return d.ArgErr()
		}
		work.filename = d.Val()
		work.sinkKey = "file:" + work.filename
		if d.NextArg() {
			return d.ArgErr()
		}
		for d.NextBlock(0) {
			if err := f.unmarshalFileWriterDirective(work, d); err != nil {
				return err
			}
		}
	}
	return nil
}

func (f *CookieFilter) unmarshalFileWriterDirective(work *cookieWork, d *caddyfile.Dispenser) error {
	switch d.Val() {
	case "roll_disabled":
		var disabled bool
		work.roll = &disabled
		if d.NextArg() {
			return d.ArgErr()
		}
	case "roll_size":
		var sizeStr string
		if !d.AllArgs(&sizeStr) {
			return d.ArgErr()
		}
		size, err := humanize.ParseBytes(sizeStr)
		if err != nil {
			return d.Errf("parsing size: %v", err)
		}
		work.rollSizeMB = int(math.Ceil(float64(size) / humanize.MiByte))
	case "roll_uncompressed":
		var uncompressed bool
		work.rollCompress = &uncompressed
		if d.NextArg() {
			return d.ArgErr()
		}
	case "roll_local_time":
		work.rollLocalTime = true
		if d.NextArg() {
			return d.ArgErr()
		}
	case "roll_keep":
		var keepStr string
		if !d.AllArgs(&keepStr) {
			return d.ArgErr()
		}
		keep, err := strconv.Atoi(keepStr)
		if err != nil {
			return d.Errf("parsing roll_keep number: %v", err)
		}
		work.rollKeep = keep
	case "roll_keep_for":
		var keepForStr string
		if !d.AllArgs(&keepForStr) {
			return d.ArgErr()
		}
		keepFor, err := caddy.ParseDuration(keepForStr)
		if err != nil {
			return d.Errf("parsing roll_keep_for duration: %v", err)
		}
		if keepFor < 0 {
			return d.Errf("negative roll_keep_for duration: %v", keepFor)
		}
		work.rollKeepDays = int(math.Ceil(keepFor.Hours() / 24))
	default:
		return d.Errf("unrecognized subdirective %s", d.Val())
	}
	return nil
}

func (m CookieFilter) prepareNetWriter(work *cookieWork) {
	work.sinkKey = m.netWriterKey(work)
	if work.dialTimeout < 0 {
		work.dialTimeout = 0
	}
}

func (m CookieFilter) netWriterKey(work *cookieWork) string {
	if work.sinkKey != "" && work.address == "" && work.netAddr.Network == "" {
		return work.sinkKey
	}
	if work.netAddr.Network != "" {
		return work.netAddr.String()
	}
	return work.address
}

func (m CookieFilter) netWriterString(work *cookieWork) string {
	if work.netAddr.Network != "" {
		return work.netAddr.String()
	}
	if work.sinkKey != "" {
		return work.sinkKey
	}
	return work.address
}

func (f *CookieFilter) provisionNetWriter(work *cookieWork) error {
	repl := caddy.NewReplacer()
	address, err := repl.ReplaceOrErr(work.address, true, true)
	if err != nil {
		return fmt.Errorf("invalid host in address: %v", err)
	}
	work.netAddr, err = caddy.ParseNetworkAddress(address)
	if err != nil {
		return fmt.Errorf("parsing network address '%s': %v", address, err)
	}
	if work.netAddr.PortRangeSize() != 1 {
		return fmt.Errorf("multiple ports not supported")
	}
	if work.dialTimeout < 0 {
		return fmt.Errorf("timeout cannot be less than 0")
	}
	work.sinkKey = work.netAddr.String()
	return nil
}

func (f *CookieFilter) unmarshalNetWriter(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		if !d.NextArg() {
			return d.ArgErr()
		}
		work.address = d.Val()
		work.sinkKey = work.address
		if d.NextArg() {
			return d.ArgErr()
		}
		for nesting := d.Nesting(); d.NextBlock(nesting); {
			switch d.Val() {
			case "dial_timeout":
				if !d.NextArg() {
					return d.ArgErr()
				}
				parsed, err := caddy.ParseDuration(d.Val())
				if err != nil {
					return d.Errf("invalid duration: %s", d.Val())
				}
				timeout := caddy.Duration(parsed)
				if d.NextArg() {
					return d.ArgErr()
				}
				work.dialTimeout = timeout
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
		}
	}
	return nil
}

func (m CookieFilter) hashField(work *cookieWork, in zapcore.Field) zapcore.Field {
	src := in.String
	if work.replaceValue != "" && src == "" {
		src = work.replaceValue
	}
	in.String = hash(src)
	return in
}

func (m CookieFilter) replaceField(work *cookieWork, in zapcore.Field) zapcore.Field {
	in.Type = zapcore.StringType
	in.String = work.replaceValue
	return in
}

func (m CookieFilter) regexpField(work *cookieWork, in zapcore.Field) zapcore.Field {
	in.String = work.compiledRegexp.ReplaceAllString(in.String, work.replaceValue)
	return in
}

func (f *CookieFilter) provisionRegexp(work *cookieWork) error {
	r, err := regexp.Compile(work.regexpRaw)
	if err != nil {
		return err
	}
	work.compiledRegexp = r
	return nil
}

func (f *CookieFilter) cookieActionNames() []string {
	names := make([]string, 0, len(f.Actions))
	seen := make(map[string]int, len(f.Actions))
	for _, a := range f.Actions {
		if a.Name == "" {
			continue
		}
		if a.Type != replaceAction && a.Type != hashAction && a.Type != deleteAction {
			continue
		}
		seen[a.Name]++
		names = append(names, a.Name)
	}
	if len(seen) == 0 && len(f.Actions) > 0 {
		for _, a := range f.Actions {
			if a.Name != "" {
				names = append(names, a.Name)
			}
		}
	}
	return names
}

func (f *CookieFilter) cookieReplaceCount() int {
	n := 0
	for _, a := range f.Actions {
		if a.Type == replaceAction {
			n++
		}
	}
	return n
}

