// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	switch values := in.Interface.(type) {
	case caddyhttp.LoggableStringArray:
		filtered := make(caddyhttp.LoggableStringArray, len(values))
		for i, value := range values {
			filtered[i] = m.filterCookieHeader(value)
		}
		in.Interface = filtered
		in.String = caddyhttp.JoinLoggedHeader(filtered)
	case []string:
		filtered := make([]string, len(values))
		for i, value := range values {
			filtered[i] = m.filterCookieHeader(value)
		}
		in.Interface = filtered
		in.String = caddyhttp.JoinLoggedHeader(caddyhttp.AsLoggableStringArray(filtered))
	default:
		in.String = m.filterCookieHeader(in.String)
	}

	return in
}

func (m CookieFilter) filterCookieHeader(header string) string {
	originRequest := http.Request{Header: http.Header{"Cookie": []string{header}}}
	cookies := originRequest.Cookies()
	transformedRequest := http.Request{Header: make(http.Header)}

OUTER:
	for _, c := range cookies {
		for _, a := range m.Actions {
			if c.Name != a.Name {
				continue
			}

			switch a.Type {
			case replaceAction:
				c.Value = a.Value
				transformedRequest.AddCookie(c)
				continue OUTER

			case hashAction:
				c.Value = hash(c.Value)
				transformedRequest.AddCookie(c)
				continue OUTER

			case deleteAction:
				continue OUTER
			}
		}

		transformedRequest.AddCookie(c)
	}

	return transformedRequest.Header.Get("Cookie")
}

